import { ProgressBarType } from "./progressBar";
const PROGRESS_BAR_PRECISION = 2;
export const isValidProggressBar = (min, max, now) => !(min > max || now < min);
export const getProgressBarValue = (min, max, now) => {
    if (!isValidProggressBar(min, max, now)) {
        return null;
    }
    const result = (now - min) / (max - min) * 100;
    return (result > 0 ? result : 0).toFixed(PROGRESS_BAR_PRECISION);
};
export const getProgressBarAttr = (type, min, max, now) => {
    const progressBarAttr = {
        className: type === ProgressBarType.Average ? "zen-progress__bar" : `zen-progress__bar zen-progress__bar--${type}`,
        role: "progressbar",
        "aria-valuemin": min,
        "aria-valuemax": max
    };
    if (now) {
        progressBarAttr["aria-valuenow"] = now;
        progressBarAttr["style"] = { width: `${now}%` };
    }
    return progressBarAttr;
};
